#!/usr/bin/env python3
"""Writes items-*.jsonl for the crew: one brief per frame (F01..F16) with the shared frame contract.
No client name, number or fact appears here: every name, price and photo is a [placeholder]."""
import json, pathlib, sys
HERE = pathlib.Path(__file__).parent

CONTRACT = """You are writing ONE storyboard frame: an HTML fragment for one section of a minimal, classy furniture website, for {dev}.
FRAME SIZE: {size}. The fragment is the INNER content of the screen. The page wraps it. Do not add html, head, body, style, script, svg, img or links.
ROOT: one <div class="col" style="height:100%"> ... </div>. Inside it, put content in <div class="in"> blocks (these add the side padding {pad}). A full-bleed element (a picture slot or a dark band) sits outside .in.
CLASSES YOU MAY USE (nothing else): hdr brand nav eyebrow poster h2 h3 lede small btn btn-o btn-t price pick dot chip rule progress steps card row band timber slot hair col grow cen in ic pl on.
 - hdr: header row (flex, space-between). brand: serif brand name. nav: row of <span> links.
 - eyebrow: small capitals label. poster: huge serif product name. h2: section headline. h3: card title. lede: grey intro line. small: grey small line.
 - btn: solid ink button. btn-o: outlined button. btn-t: text link. Put icons inside: <i class="ic ic-message-circle"></i>. Icon names allowed: menu message-circle phone map-pin arrow-right ruler check clock instagram plus chevron-down.
 - price: serif price. pick: a size/preset button (add class "on" for the chosen one). dot: fabric colour dot, give it style="background:#hex" (placeholder colours only), class "on" for chosen. chip: fabric chip holding a dot and a label.
 - rule: hairline. progress: hairline with <i style="width:50%"></i> inside. steps: row of <span>, class "on" on the current. card: column. row: flex row, space-between.
 - band: dark band wrapper (full width). timber: bordered card inside a band. hair: short timber rule. col: flex column. grow: flex-grow 1. cen: centred text.
 - slot: an empty picture slot. Always exactly: <div class="slot" data-label="LABEL" data-size="WxH" style="width:..;height:.."></div>. Put NO text inside it. Never draw furniture. Never use svg.
 - Inline style is allowed ONLY for layout: width, height, display, flex, grid, gap, margin, padding, position, top, left, right, bottom, text-align, align-items, justify-content, flex-direction, overflow, border-radius, background colour of a dot. No fonts, no colours elsewhere, no font-size.
TEXT RULES: copy every quoted text EXACTLY. Anything in square brackets like [Brand name] stays exactly as written, brackets included. Never invent a name, price, product, address or number. British English. No em dashes or en dashes. No comma before and, or, but. No emoji.
LAYOUT RULES: {layout}
Return ONLY one fenced html code block with the fragment.

THE FRAME:
"""

PH_LAYOUT = "Phone: content is CENTRED, buttons are full width, the content area is 390 wide and 756 tall, so keep it inside 756px with nothing clipped. Tap targets at least 44px tall."
DK_LAYOUT = "Desk: brand and headline start at the LEFT gutter (never a centred frame), nav sits at the right gutter. Use the full 1344px inside the padding. Keep everything inside 900px height with nothing clipped."

B = {}
B["F01"] = ("phone", """SECTION 1 HEADER, menu open. In .in: a hdr row with a menu icon button at the left, the brand "[Brand name]" in the centre (class brand) and a message-circle icon at the right (all three vertically centred, row of 56px). Below it a rule, then a centred column of four large serif links using class h2: "Shop", "Build yours", "Craft", "Visit" with 20px gaps, then a full width btn with the message-circle icon and the text "Message us". Leave the lower part calm and empty. Above the hdr row put nothing.""")
B["F02"] = ("desk", """SECTION 1 HEADER, two states stacked, each 88px high, with a small eyebrow label above each: "At the top" and "Scrolled". Each state is a hdr row: brand "[Brand name]" at the left gutter, then at the right gutter a nav of four spans "Shop", "Build yours", "Craft", "Visit" and a btn with the message-circle icon and "Message us". The "Scrolled" state is the same row 64px high with a rule under it. Between the two states leave 120px of empty space. Fill the rest with nothing.""")
B["F03"] = ("phone", """SECTION 2 HERO. Top: a hdr row (menu icon left, brand "[Brand name]" centre, message-circle icon right). Then a centred column inside .in: eyebrow "[Category] · [Timber] · [Fabric]"; poster "[Piece name]" centred; then a relatively positioned block 350px wide and 210px tall holding a slot (data-label "Hero photo: the piece in a calm room" data-size "1600x1200", width 100%, height 210px) with a second small slot class "slot" (data-label "Pencil drawing" data-size "1200x1200", width 96px, height 96px, position absolute, right 8px, bottom 8px) overlapping its bottom right corner. Then a centred lede "Buy it ready. Or build it yours." Then a full width btn "Ready to buy · from LKR [price]" and under it a full width btn-o "Build your own" with the arrow-right icon after the text. Stack with 12px gaps.""")
B["F04"] = ("desk", """SECTION 2 HERO. A hdr row (brand "[Brand name]" at the left gutter, nav "Shop" "Build yours" "Craft" "Visit" and a btn "Message us" with the message-circle icon at the right gutter). Below, a two column layout, gap 64px, left column 560px wide starting at the left gutter, vertically centred in the remaining height: eyebrow "[Category] · [Timber] · [Fabric]"; poster "[Piece name]"; lede "Buy it ready. Or build it yours."; a row of two buttons: btn "Ready to buy · from LKR [price]" and btn-o "Build your own" with arrow-right after the text; below a row of three pick buttons "[Size 1]" "[Size 2]" "[Size 3]" and three dots (fabric colours, the first one class on). Right column fills the rest (about 720px): a slot (data-label "Hero photo: the piece in a calm room" data-size "1600x1200", width 100%, height 520px) and over its bottom left a smaller slot (data-label "Pencil drawing" data-size "1200x1200", width 220px, height 220px, position absolute, left -48px, bottom -24px) with three small lines under the drawing: "[Width] mm", "[Depth] mm", "[Seat height] mm" in class small.""")
B["F05"] = ("phone", """SECTION 3 ROOMS. In .in: a row of four pick buttons "[Living]" "[Dining]" "[Bedroom]" "[Study]" (first has class on), 8px gaps, small. Then h2 "One home. Four rooms." (left aligned is not allowed: centred). Then lede "Walk through. Tap any piece you like." Then a FULL BLEED slot outside .in: data-label "Room photo 1 of 4, same camera spot" data-size "2400x1350", width 100%, height 300px, relatively positioned, containing one chip at its bottom left (position absolute, left 16px, bottom 36px) holding a dot (class on) and the text "[Piece name]". Under the slot, in .in: a row with small "01 / 04" at the left and a btn-t "Next room" with the arrow-right icon at the right, and under it a progress hairline with <i style="width:25%"></i>.""")
B["F06"] = ("desk", """SECTION 3 ROOMS. A hdr row (brand "[Brand name]" at the left gutter, nav at the right gutter, btn "Message us" with message-circle icon). Below, two columns, gap 48px: a left column 340px wide starting at the left gutter with h2 "One home. Four rooms.", lede "Walk through. Tap any piece you like.", then four stacked pick buttons "[Living]" "[Dining]" "[Bedroom]" "[Study]" (first has class on, each full column width, 48px tall), then small "01 / 04". The right column fills the rest (about 940px): a slot (data-label "Room photo 1 of 4, same camera spot" data-size "2400x1350", width 100%, height 520px, position relative) containing two chips (position absolute) each holding a dot (class on) and "[Piece name]", one at left 80px top 300px and one at left 520px top 360px. Under the slot a progress hairline with <i style="width:25%"></i>.""")
B["F07"] = ("phone", """SECTION 4 READY TO BUY, first of four cards. In .in: h2 "Ready to take home." centred; lede "[One line: delivery promise]" centred. Then ONE card (class card) 350px wide: slot (data-label "Piece photo 1" data-size "1000x1250", width 100%, height 300px); h3 "[Piece name]"; small "[Timber] frame · [Fabric] · [Detail]"; a row of three dots (first class on, placeholder colours); then a row (class row): price "LKR [price]" at the left and a btn "Buy on WhatsApp" with the message-circle icon after the text at the right. Under the card a small centred "01 / 04" and a progress hairline with <i style="width:25%"></i>.""")
B["F08"] = ("desk", """SECTION 4 READY TO BUY. A hdr row (brand "[Brand name]" at the left gutter, nav at the right gutter, btn "Message us"). Then at the left gutter: h2 "Ready to take home." and lede "[One line: delivery promise]". Then a row of FOUR equal cards (class card, gap 24px, each about 318px wide): slot (data-label "Piece photo N" with N=1..4, data-size "1000x1250", width 100%, height 330px); h3 "[Piece name]"; small "[Timber] frame · [Fabric] · [Detail]"; three dots (first class on); a row with price "LKR [price]" at the left and a btn "Buy" with the message-circle icon after the text at the right.""")
B["F09"] = ("phone", """SECTION 5 BUILD YOURS. Everything centred inside .in, 12px rhythm. h2 "Make it yours." then lede "Pick a start, a size and a fabric. The price moves with you." Then steps with four spans "01 Start" "02 Size" "03 Fabric" "04 Send" (second has class on) and under it a progress hairline <i style="width:50%"></i>. Then a row of three pick buttons "01" "02" "03" (first on) and under it small "[Preset name]". Then a slot (data-label "Drawing with measurements" data-size "1200x1200", width 100%, height 130px) with small "[Width] mm · [Depth] mm · [Seat height] mm" under it. Then a row of three pick buttons "[Size 1]" "[Size 2]" "[Size 3]" (second on). Then a row of two chips each with a dot and a label "[Fabric 1]" "[Fabric 2]" (first on). Then a row: price "LKR [price]" at the left and small "live price" at the right. Last a full width btn "Send my build on WhatsApp" with the message-circle icon. It must all fit 756px, so compress gaps if needed.""")
B["F10"] = ("desk", """SECTION 5 BUILD YOURS. A hdr row (brand "[Brand name]" at the left gutter, nav at the right gutter, btn "Message us"). Below: at the left gutter h2 "Make it yours." and lede "Pick a start, a size and a fabric. The price moves with you." Then steps spanning the full 1344px with four spans "01 Start" "02 Size" "03 Fabric" "04 Send" (second has class on) and a progress hairline <i style="width:50%"></i>. Then two columns, gap 56px: left column 560px: slot (data-label "Drawing with measurements" data-size "1200x1200", width 100%, height 400px) with a row beneath of three small lines "[Width] mm" "[Depth] mm" "[Seat height] mm". Right column: small label "Start", three pick buttons "01" "02" "03" (first on) with small "[Preset name]"; small label "Size", three pick buttons "[Size 1]" "[Size 2]" "[Size 3]" (second on); small label "Fabric", a row of three chips each with a dot and "[Fabric 1]" "[Fabric 2]" "[Fabric 3]" (first on) and beside them a slot (data-label "Weave close-up" data-size "800x800", width 120px, height 120px). Last in the right column a row: price "LKR [price]" at the left (with small "live price" under) and a btn "Send my build on WhatsApp" with the message-circle icon.""")
B["F11"] = ("phone", """SECTION 6 DETAIL ROW. In .in: h2 "Look closer." centred. Then THREE items stacked with 20px gaps, each a row: a slot at the left (data-label "Detail N" with N=1..3, data-size "800x800", width 120px, height 120px) and at its right a column: eyebrow "0N" (01, 02, 03), h3 "[Part N]" (1, 2, 3) and small "[One line: what it does for you]". Items are left aligned inside, the headline is centred.""")
B["F12"] = ("desk", """SECTION 6 DETAIL ROW. A hdr row (brand "[Brand name]" at the left gutter, nav at the right gutter, btn "Message us"). Then at the left gutter h2 "Look closer.". Then a row of THREE equal columns (gap 32px, each about 427px wide), each a card: slot (data-label "Detail N" with N=1..3, data-size "800x800", width 100%, height 427px); eyebrow "0N" (01, 02, 03); h3 "[Part N]" (1, 2, 3); small "[One line: what it does for you]".""")
B["F13"] = ("phone", """SECTION 7 CRAFT BAND. The root is a band (class band) filling the whole height. At its top a full bleed slot (data-label "Workshop: a pair of hands at a bench" data-size "2400x1200", width 100%, height 240px). Then in .in, 16px gaps: eyebrow "The workshop"; h2 "[One line from the workshop]"; a timber card (class timber) holding eyebrow "Timber", h3 "[Timber species]", small "[Origin]" and small "[Why it lasts: one line]"; then a row: a round slot (data-label "Maker" data-size "600x600", width 64px, height 64px, border-radius 50%) and next to it small "Made by [Maker name]". All text left aligned inside the dark band.""")
B["F14"] = ("desk", """SECTION 7 CRAFT BAND. The root is a band (class band) filling the whole 1440 by 900. Two columns with no gap: the LEFT half is a full bleed slot touching the left, top and bottom screen edges (data-label "Workshop: a pair of hands at a bench" data-size "2400x1200", width 720px, height 100%). The right half has padding 0 96px 0 72px and is a column centred vertically: eyebrow "The workshop"; h2 "[One line from the workshop]"; a timber card (class timber) holding eyebrow "Timber", h3 "[Timber species]", small "[Origin]" and small "[Why it lasts: one line]"; a row with a round slot (data-label "Maker" data-size "600x600", width 72px, height 72px, border-radius 50%) and small "Made by [Maker name]". No header row in this frame.""")
B["F15"] = ("phone", """SECTION 8 VISIT AND CONTACT with footer. In .in, centred, 12px rhythm: h2 "Come and sit on it."; a row with the map-pin icon and small "[Showroom address]"; a row with the clock icon and small "[Opening hours]"; a full width btn "WhatsApp us" with the message-circle icon; a full width btn-o "Call [Phone number]" with the phone icon; a slot (data-label "Map" data-size "1200x800", width 100%, height 130px). Then a rule, then the footer centred: brand "[Brand name]"; a row of small "Shop" "Build yours" "Craft" "Visit"; a row with the instagram icon and small "[Instagram handle]"; small "© [Year] [Brand name]". It must all fit 756px, so compress.""")
B["F16"] = ("desk", """SECTION 8 VISIT AND CONTACT with footer. A hdr row (brand "[Brand name]" at the left gutter, nav at the right gutter, btn "Message us"). Then two columns, gap 64px: the left column 520px starting at the left gutter: h2 "Come and sit on it."; a row with the map-pin icon and small "[Showroom address]"; a row with the clock icon and small "[Opening hours]"; a row of two buttons: btn "WhatsApp us" with the message-circle icon and btn-o "Call [Phone number]" with the phone icon. The right column fills the rest: a slot (data-label "Map" data-size "1200x800", width 100%, height 380px). At the bottom of the frame a footer: a rule, then a row with brand "[Brand name]" at the left gutter, a nav of small "Shop" "Build yours" "Craft" "Visit" in the middle and at the right gutter the instagram icon with small "[Instagram handle]" and small "© [Year]".""")

SIZES = {"phone": ("a PHONE (390 by 844)", "390 by 756 content area", "20px", PH_LAYOUT), "desk": ("a DESK screen (1440 by 900)", "1440 by 900", "48px", DK_LAYOUT)}

def item(code):
    dev, text = B[code]
    d, size, pad, lay = SIZES[dev]
    return {"ref": code, "text": CONTRACT.format(dev=d, size=size, pad=pad, layout=lay) + text}

if __name__ == "__main__":
    which = sys.argv[1:] or sorted(B)
    out = HERE / ("items-" + "-".join(which) + ".jsonl" if len(which) < 16 else "items-all.jsonl")
    out.write_text("\n".join(json.dumps(item(c)) for c in which) + "\n")
    print("wrote", out.name, len(which), "items")
